import pandas as pd, numpy as np
pd.set_option("display.width",220); pd.set_option("display.max_columns",40); pd.set_option("display.max_colwidth",70)
C="RNA-seq/results/evidence_passports/candidates/gene-catalog-corrected-r8-20261009T142027Z/"
g=pd.read_parquet(C+"passport_gene_index.parquet"); e=pd.read_parquet(C+"passport_evidence_long.parquet")
deg=pd.read_csv("RNA-seq/results/manuscript_release/candidates/bulk-corrected-controls-20261008T162308Z-reproduction/primary_source_controls/deg_results.csv"); deg["ens"]=deg.gene.str.replace(r"\..*","",regex=True)
col=pd.read_csv("GWAS/finemapping/results/susie_coloc_r2_20260924T053244Z/gene_level_coloc_tier12.csv")
gen=pd.read_csv(C+"preflight/gen_identity_adjudication_v1/gen_frozen_classes_ensembl_adjudicated.tsv",sep="\t",usecols=["gene_symbol","ensembl_bulk","ensembl_genetic","adjudicated_ensembl_id","static_class","bulk_logFC","bulk_padj","coloc_best_susie_pp4","coloc_best_abf_pp4","identity_resolution_rule","source_row_count"])
six=["MATR3","ITFG2-AS1","CTSLP2","SUGT1P3","POLR2J4","PAXX"]
print(gen[gen.gene_symbol.isin(six)].to_string())
print(deg[deg.symbol.isin(six)][["gene","symbol","logFC","padj"]].to_string())
print(gen.identity_resolution_rule.value_counts().to_string()); print("rows with bulk!=genetic ensembl:",((gen.ensembl_bulk.notna())&(gen.ensembl_genetic.notna())&(gen.ensembl_bulk!=gen.ensembl_genetic)).sum())
md=sorted(set(deg.ens)-set(g.ensembl_id)); mc=sorted(set(col.ensembl)-set(g.ensembl_id))
q=pd.read_csv(C+"preflight/gen_identity_adjudication_v1/gen_identity_quarantine.tsv",sep="\t"); print(list(q.columns))
blob=" ".join(q.astype(str).agg(" ".join,axis=1))
un=[x for x in md if x not in blob]; print("deg absent not in quarantine text:",un, deg[deg.ens.isin(un)][["symbol","logFC","padj"]].to_dict("records"))
gb=" ".join(gen.ensembl_bulk.astype(str))+" "+" ".join(gen.ensembl_genetic.astype(str))
print("of those, present in GEN source id fields:",[x for x in un if x in gb])
unc=[x for x in mc if x not in blob]; print("coloc absent not in quarantine:",unc,[x for x in unc if x in gb])
w=e[e.evidence_domain=="genetics"].copy(); w["est"]=pd.to_numeric(w.estimate.astype("Float64"),errors="coerce").astype(float)
hi=w[(w.call_state=="indeterminate")&(w.est>0.5)].merge(col,left_on="ensembl_id",right_on="ensembl",how="left")
print("indeterminate genetics with PP.H4>0.5:",len(hi),"estimate==ABF:",int(np.isclose(hi.est,hi.coloc_best_abf_pp4).sum()),"susie state:",hi.susie_state_t12.value_counts(dropna=False).to_dict())
print(hi.sort_values("est",ascending=False)[["symbol","est","dataset_id","phenotype","coloc_best_susie_pp4","allowed_wording"]].head(5).to_string())
print("columns naming the COLOC method in evidence rows:",[c for c in e.columns if "method" in c.lower()], e[e.evidence_domain=="genetics"].assay.unique())
print("untested-class genes with a supported row:", 698+10, "| e.g.", )
x=e[(e.call_state=="supported")].merge(g[g.primary_evidence_class=="untested"][["ensembl_id"]],on="ensembl_id")
print(x.evidence_domain.value_counts().to_dict()); print(x[x.evidence_domain=="transcriptomics"].assign(a=lambda d:d.estimate.astype(float).abs()).sort_values("a",ascending=False)[["symbol","estimate","q_value"]].head(8).to_string())
